ation="vertical">\n              <input id="block-end-input" type="text" placeholder="Enter amount" />\n              <footer data-align="end">\n                <span>USD</span>\n              </footer>\n            </div>\n            <p>Footer positioned below the input.</p>\n          </div>\n          <div class="field">\n            <label for="block-end-textarea">Textarea</label>\n            <div class="input-group" data-orientation="vertical">\n              <textarea id="block-end-textarea" placeholder="Write a comment..."></textarea>\n              <footer data-align="end">\n                <span>0/280</span>\n                <button type="button" class="btn ml-auto" data-size="sm">Post</button>\n              </footer>\n            </div>\n            <p>Footer positioned below the textarea.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </article>\n  <article class="space-y-3">\n    <h3 class="text-sm font-medium text-muted-foreground">Icon</h3>\n    <div class="flex min-h-40 flex-wrap items-center justify-center gap-4 rounded-xl border p-6 sm:p-10">\n      <div class="w-full max-w-sm">\n        <div class="grid gap-6">\n          <div class="input-group">\n            <input type="text" placeholder="Search..." />\n            <span data-align="start" aria-hidden="true"><i data-lucide="search" aria-hidden="true"></i></span>\n          </div>\n          <div class="input-group">\n            <input type="email" placeholder="Enter your email" />\n            <span data-align="start" aria-hidden="true"><i data-lucide="mail" aria-hidden="true"></i></span>\n          </div>\n          <div class="input-group">\n            <input type="text" placeholder="Card number" />\n            <span data-align="start" aria-hidden="true"><i data-lucide="credit-card" aria-hidden="true"></i></span>\n            <span data-align="end" aria-hidden="true"><i data-lucide="check" aria-hidden="true"></i></span>\n          </div>\n          <div class="input-g